            row["microphone_footer_and_wizard"].update({"presentation": identity(mic_destination), "assets": microphone_assets})
            mixer_body = module_by_role["current_ui_stream_mixer_v2"]["body"]
            mixer_labels = {}
            for symbol in sorted(set(re.findall(r'W\.([\w$]+)', mixer_body))):
                exported_label = re.search(re.escape(symbol) + r':\(\)=>([\w$]+)', labels_body)
                if exported_label is None:
                    raise ValueError("Current stream mixer label export is absent: " + symbol)
                label_value = re.search(r'(?<![\w$])' + re.escape(exported_label[1]) + r'=("[^"\\]*(?:\\.[^"\\]*)*")', labels_body)
                if label_value is None:
                    raise ValueError("Current stream mixer label value is unresolved: " + symbol)
                mixer_labels[symbol] = json.loads(label_value[1])
            mixer_assets = {}
            for key, filename in {
                    "broadcast": "icon_broadcast", "broadcast-disabled": "icon_broadcast_disable",
                    "headphone": "icon_headphone", "headphone-disabled": "icon_headphone_audio_listen_disable-1",
                    "listen": "icon_listening_ear", "listen-disabled": "icon_listening_ear_disabled",
                    "link": "icon_link-1", "link-hover": "icon_link-1_hover",
                    "unlink": "icon_unlink-1", "unlink-hover": "icon_unlink-1_hover",
                    "link-left": "link_line_left", "link-right": "link_line_right",
                    "close": "close-no-background", "menu": "menu-button",
                    "warning": "warning", "device-warning": "warning-icon", "shortcut-warning": "icon_warning"}.items():
                media_originals = [source for source in ui_originals if re.search('/' + re.escape(filename) + r'\.[^/]+\.svg$', source["url"])]
                if len(media_originals) != 1:
                    raise ValueError("Current stream mixer resource is absent or ambiguous: " + filename)
                original = media_originals[0]
                runtime_key = "synapse/seiren-stream-" + key + ".svg"
                mixer_assets[key] = {"runtime_key": runtime_key, "original": original}
            import base64
            for key, selector in (("add", ".add-input-button .add-icon"), ("check", ".routing-checkbox-container .routing-checkmark:after")):
                embedded = [(entry["original"], rule) for entry in css for rule in entry["complete_rules"]
                            if selector in rule["selector"] and "data:image/png;base64," in rule["body"]]
                if len(embedded) != 1:
                    raise ValueError("Current stream mixer embedded bitmap is unresolved: " + key)
                original, rule = embedded[0]
                encoded = re.search(r'data:image/png;base64,([A-Za-z0-9+/=]+)', rule["body"])[1]
                bitmap = base64.b64decode(encoded, validate=True)
                digest = hashlib.sha256(bitmap).hexdigest()
