                    (("mirror",), "ui_image_page", "mw_mirror_task", "request_camera_edit -> compile_camera_edit", "SetMirrorVideo extension"),
                    (("resolution",), "ui_source_resolution", "mw_resolution_task", "camera_media.rs restart_camera_media", "exact requested local Media Foundation mode"),
                    (("view-preset", "zoom", "pan-tilt"), "ui_view_presets", "mw_view_preset_task", "request_camera_edit -> compile_camera_edit", "CameraControl Zoom/Pan/Tilt"),
                    (("shortcut-key",), "ui_shortcut_capture", "mw_shortcut_registration", "camera_shortcuts.rs Session/poll_camera_shortcuts", "local OS shortcut registration, then mounted view-mode effect"),
                    (("autofocus", "focus", "focus-tracking"), "ui_focus", "mw_focus_task", "request_camera_edit -> compile_camera_edit", "CameraControl Focus and source-specific FDAF/sensitivity extension"),
                    (("auto-exposure", "iso", "shutter", "metering", "compensation", "reset-exposure"),
                     "ui_exposure", "mw_exposure_task", "camera_exposure_state.rs -> request_camera_edit -> compile_camera_edit", "CameraControl Exposure and source-specific ISO/shutter/metering/EV extensions"),
