            "crates/razer-discovery/src/direct/mouse_receiver_polling_tests.rs", "crates/razer-discovery/src/direct/platform/windows.rs", "crates/razer-ipc/src/lib.rs",
            "crates/razer-service/src/runtime/mod.rs", "crates/razer-service/src/runtime/portable.rs",
            "crates/razer-service/src/runtime/windows/device_reads.rs", "crates/razer-service/src/runtime/windows/native.rs",
            "crates/razer-device/src/mouse/mouse_current_dpi.rs", "crates/razer-device/src/mouse/mouse_dpi_stages.rs",
